import { SCENES } from "../edit/scenes.js";
import { LAYOUT, place } from "../edit/timeline.js";
import { p, outCubic, glide, ease, move } from "../core/motion.js";

export const MARGIN = 56;
// Scene times are on the shot's clock (source seconds for a clip); everything here runs in output seconds.
const timed = SCENES.map((e) => ({ ...e, at: place(e.shot, e.a), out: place(e.shot, e.b) }));
// A scene is the pieces of one shot that leave together (same b).
const sceneStart = (e) => Math.min(...timed.filter((o) => o.shot === e.shot && o.b === e.b).map((o) => o.at));

