  if (v === undefined) return;
  if (v === "start" || v === "end" || (isNumber(v) && v >= 0)) return;
  if (isObject(v) && Number.isInteger(v.word) && v.word >= 0) return;
  c.bad(path, 'must be "start", "end", a number of seconds, or { "word": <index> }');
